class StructAccessor(ArrowAccessor):
    """
    Accessor object for structured data properties of the Series values.

    Parameters
    ----------
    data : Series
        Series containing Arrow struct data.
    """

    def __init__(self, data=None) -> None:
        super().__init__(
            data,
            validation_msg=(
                "Can only use the '.struct' accessor with 'struct[pyarrow]' "
                "dtype, not {dtype}."
            ),
        )

    def _is_valid_pyarrow_dtype(self, pyarrow_dtype) -> bool:
        return pa.types.is_struct(pyarrow_dtype)

    @property
    def dtypes(self) -> Series:
        """Return the dtype object of each child field of the struct."""
        from pandas import Series

        return Series(
            [ArrowDtype(field.type) for field in self._pa_dtype],
            index=[field.name for field in self._pa_dtype],
            dtype=object,
        )

    def explode(self) -> DataFrame:
        """Extract all child fields of a struct as a DataFrame."""
        from pandas import DataFrame

        result = DataFrame(
            {index: self.field(index) for index in range(len(self._pa_dtype))},
            index=self._data.index,
        )
        result.columns = [field.name for field in self._pa_dtype]
        return result

    def field(
        self,
        name_or_index: (
            list[str]
            | list[bytes]
            | list[int]
            | pc.Expression
            | bytes
            | str
            | int
        ),
    ) -> Series:
        """Extract a child field of a struct as a Series."""
        from pandas import Series

        if isinstance(name_or_index, pc.Expression):
            result_name = str(name_or_index)
            selection = name_or_index
            selected = pc.struct_field(self._pa_array, selection)
        else:
            if is_list_like(name_or_index):
                selection = list(name_or_index)
            else:
                selection = [name_or_index]

            if not selection or not all(
                isinstance(item, (str, bytes, int)) for item in selection
            ):
                raise ValueError(
                    "name_or_index must be an int, str, bytes, "
                    "pyarrow.compute.Expression, or a non-empty list of those"
                )

            selected = pc.struct_field(self._pa_array, selection)
            current_type = self._pa_dtype
            selected_field = current_type[selection[0]]
            for item in selection[1:]:
                selected_field = selected_field.type[item]
            result_name = selected_field.name

        return Series(
